import type { BreachRecord } from "../../🟦️.ts";

/** 🚫️Explicit ticket-cited allowlist for generated bytes that must remain indexed. */
const POLICY_INDEXED_GENERATED_ALLOWLIST = new Set<string>([
  "🧰️framework/🛍️products/💻️os/🔨️modules/📺️renderer/🧑‍🎨engine/🎯️targets/🧊️wgpu/🎞️frame-worker/🤖️generated/🟨️.js",
]);

const POLICY_INDEXED_GENERATED_RULES: readonly { id: string; reason: string; test: (path: string) => boolean }[] = [
  { id: "wasm-binary", reason: "WASM binaries are build output (`**/*.wasm`).", test: (path) => /\.(wasm|cwasm)$/u.test(path) },
  { id: "wasm-bindgen-types", reason: "wasm-bindgen emits `*_bg.wasm.d.ts` beside the JS glue.", test: (path) => /_bg\.wasm\.d\.ts$/u.test(path) },
  { id: "jco-component", reason: "jco emits `*_component.js`, `*_component.d.ts`, and `*_component.core.wasm`.", test: (path) => /_component\.(js|d\.ts)$/u.test(path) || /_component\.core\.wasm$/u.test(path) },
  { id: "wasm-pack-bindings-tree", reason: "wasm-pack web builds publish under `🕸️bindings/`.", test: (path) => path.includes("/🕸️bindings/") },
  { id: "jco-browser-bundles", reason: "jco browser materialization lives under fixture `🌐️browser-bundles/`.", test: (path) => path.includes("/🌐️browser-bundles/") },
  { id: "generated-tree", reason: "Generated trees use `🤖️generated/` (see repo `.gitignore`).", test: (path) => path.includes("/🤖️generated/") },
  { id: "wasm-pack-pkg", reason: "wasm-pack `pkg/` directories are never source.", test: (path) => path.includes("/pkg/") || path.endsWith("/pkg") },
];

function policyIndexedGeneratedPaths(repoRoot: string): string[] {
  const result = Bun.spawnSync(["git", "ls-files", "-z"], { cwd: repoRoot });
  if (result.exitCode !== 0) throw new Error(`git ls-files failed: ${result.stderr.toString()}`);
  return result.stdout
    .toString()
    .split("\0")
    .filter(Boolean)
    .map((path) => path.replaceAll("\\", "/"));
}

/** 🧹️Fails when Git still indexes wasm/jco/wasm-pack generated artifacts outside the explicit allowlist. */
export function policyIndexedGeneratedOutputBreaches(repoRoot: string): BreachRecord[] {
  const breaches: BreachRecord[] = [];
  for (const path of policyIndexedGeneratedPaths(repoRoot)) {
    if (POLICY_INDEXED_GENERATED_ALLOWLIST.has(path)) continue;
    if (path.startsWith(".🧬semio/🦑️repo/🎫️tickets/")) continue;
    for (const rule of POLICY_INDEXED_GENERATED_RULES) {
      if (!rule.test(path)) continue;
      breaches.push({
        id: `indexed-generated-${rule.id}-${path}`,
        summary: `Git indexes generated output: ${path}`,
        kind: "repo/indexed-generated-output",
        scope: path,
        priority: "high",
        reason: rule.reason,
        solution: `Run git rm --cached on ${path}; ensure the path is ignored and regenerate via the owning Nx/wasm/jco target instead of committing bytes.`,
      });
      break;
    }
  }
  return breaches;
}

export function policyIndexedGeneratedOutputViolations(repoRoot: string): string[] {
  return policyIndexedGeneratedOutputBreaches(repoRoot).map((breach) => breach.scope);
}
